// 编写日期：2026年8月5日
// 作者：zidong
// 程序说明：图书管理系统 - 用户类

#ifndef USER_HPP
#define USER_HPP

#include <string>
#include <vector>

using std::string;
using std::vector;

// 用户类：普通用户，可借阅与归还图书
class User {
public:
    User() : username(""), password("") {}
    User(const string& name, const string& pwd)
        : username(name), password(pwd) {}

    // 获取用户名
    string getUsername() const { return username; }
    // 获取密码
    string getPassword() const { return password; }

    // 借阅图书：记录借阅的图书编号，若成功返回 true
    bool borrowBook(const string& bookId) {
        for (size_t i = 0; i < borrowedIds.size(); ++i) {
            if (borrowedIds[i] == bookId) return false; // 已借过该书
        }
        borrowedIds.push_back(bookId);
        return true;
    }

    // 归还图书：移除借阅记录，若未借过返回 false
    bool returnBook(const string& bookId) {
        for (size_t i = 0; i < borrowedIds.size(); ++i) {
            if (borrowedIds[i] == bookId) {
                borrowedIds.erase(borrowedIds.begin() + i);
                return true;
            }
        }
        return false;
    }

    // 是否已借阅该书
    bool hasBorrowed(const string& bookId) const {
        for (size_t i = 0; i < borrowedIds.size(); ++i) {
            if (borrowedIds[i] == bookId) return true;
        }
        return false;
    }

    // 获取当前借阅的图书数量
    size_t borrowedCount() const { return borrowedIds.size(); }

    // 获取所有已借阅的图书编号
    const vector<string>& getBorrowedIds() const { return borrowedIds; }

private:
    string username;   // 用户名
    string password;   // 密码
    vector<string> borrowedIds; // 当前借阅的图书编号列表
};

#endif // USER_HPP
